<template>
  <div class="event-results">
    <header class="results-heading">
      <div><p class="eyebrow">At the tables</p><h1>Follow the <em>field.</em></h1><p>Find your table, follow the qualifiers and see who makes the final.</p></div>
      <button class="refresh-button" :disabled="refreshing" @click="$emit('refresh')">{{ refreshing ? 'Updating…' : '↻ Refresh' }}</button>
    </header>

    <ol class="round-progress" aria-label="Tournament progress">
      <li v-for="(phase, index) in phases" :key="phase.key" :class="{ current: phaseIndex === index, done: phaseIndex > index }" :aria-current="phaseIndex === index ? 'step' : undefined"><span>{{ phaseIndex > index ? '✓' : index + 1 }}</span><strong>{{ phase.label }}</strong><small>{{ phaseIndex > index ? 'Complete' : phaseIndex === index ? (event?.stage === 'completed' ? 'Complete' : 'Current stage') : 'Up next' }}</small></li>
    </ol>

    <p v-if="error" class="results-notice" role="status">{{ snapshot ? 'Showing the last available update. ' : '' }}{{ error }}</p>
    <section v-if="loading" class="results-card empty-results" aria-live="polite"><span class="empty-tile" aria-hidden="true">一</span><h2>Getting the latest update…</h2></section>
    <template v-else-if="snapshot">
      <div class="results-toolbar">
        <label class="player-search"><span>Find a player</span><input v-model="search" type="search" placeholder="Search by name" autocomplete="off"></label>
        <p class="update-note"><span class="live-dot" aria-hidden="true"></span>{{ snapshot.last_certified ? 'Results certified' : 'Latest publication' }}<strong>{{ formattedUpdate }}</strong></p>
      </div>

      <section v-if="snapshot.final?.length" class="results-card champion-card">
        <p class="eyebrow">Riichi Open I champion</p><h2>{{ snapshot.final[0].display_name }}</h2><p>One final table. A well-earned win.</p>
        <ol><li v-for="row in snapshot.final" :key="row.participant_id"><strong>{{ ordinal(row.rank) }}</strong><span>{{ row.display_name }}</span><small>{{ score(row.score) }} pts</small></li></ol>
      </section>

      <section v-if="assignments.length" class="results-card">
        <div class="card-heading"><div><p class="eyebrow">Published seating</p><h2>{{ humanize(snapshot.assignment_round || event?.stage) }}</h2></div><span class="soft-badge">{{ assignments.length }} {{ assignments.length === 1 ? 'table' : 'tables' }}</span></div>
        <div class="seating-grid"><article v-for="table in filteredAssignments" :key="table.table_number"><h3>Table <strong>{{ table.table_number }}</strong></h3><ul><li v-for="seat in table.seats" :key="seat.seat_wind" :class="{ 'matched-player': search && matches(seat.display_name) }"><span class="wind-label">{{ seat.seat_wind }}</span><strong>{{ seat.display_name }}</strong></li></ul></article></div>
        <p v-if="!filteredAssignments.length" class="no-matches">No published table matches “{{ search }}”.</p>
      </section>

      <section v-if="snapshot.standings?.length" class="results-card">
        <div class="card-heading"><div><p class="eyebrow">Certified results</p><h2>{{ event?.stage === 'completed' ? 'Final qualification standings' : 'Qualification standings' }}</h2></div><span class="soft-badge">Certified only</span></div>
        <p class="table-note">Penalties are already deducted from the total. The Top 4 advance to the final.</p>
        <div class="desktop-standings table-scroll"><table><caption class="sr-only">Certified qualification scores</caption><thead><tr><th scope="col">Rank</th><th scope="col">Player</th><th scope="col">Q1</th><th scope="col">Q2</th><th scope="col">Penalties</th><th scope="col">Total</th></tr></thead><tbody><tr v-for="row in filteredStandings" :key="row.participant_id" :class="{ finalist: isFinalist(row) }"><td><span class="rank-number">{{ row.rank }}</span></td><th scope="row">{{ row.display_name }}<small v-if="row.is_substitute">Substitute · not eligible for final</small><small v-else-if="isFinalist(row)" class="finalist-label">Finalist</small></th><td>{{ score(row.qualifier_1) }}</td><td>{{ score(row.qualifier_2) }}</td><td>{{ deduction(row.penalties) }}</td><td class="total-score">{{ score(row.total) }}</td></tr></tbody></table></div>
        <ol class="mobile-standings"><li v-for="row in filteredStandings" :key="row.participant_id" :class="{ finalist: isFinalist(row) }"><div class="player-line"><span class="rank-number">{{ row.rank }}</span><div><strong>{{ row.display_name }}</strong><small v-if="row.is_substitute">Substitute</small><small v-else-if="isFinalist(row)" class="finalist-label">Finalist</small></div><strong class="total-score">{{ score(row.total) }}<small>total</small></strong></div><dl><div><dt>Qualifier 1</dt><dd>{{ score(row.qualifier_1) }}</dd></div><div><dt>Qualifier 2</dt><dd>{{ score(row.qualifier_2) }}</dd></div><div><dt>Penalties</dt><dd>{{ deduction(row.penalties) }}</dd></div></dl></li></ol>
        <p v-if="!filteredStandings.length" class="no-matches">No certified player matches “{{ search }}”.</p>
      </section>
      <section v-else class="results-card waiting-scores"><h2>Tables are ready. Scores come next.</h2><p>Results appear here once the organiser certifies a whole round.</p></section>

      <p v-if="snapshot.message" class="table-note">{{ snapshot.message }}</p>
    </template>
    <section v-else class="results-card empty-results"><span class="empty-tile" aria-hidden="true">一</span><p class="eyebrow">The field is taking shape</p><h2>{{ error ? 'Updates are temporarily unavailable' : 'The first draw is still to come.' }}</h2><p>{{ error ? 'Use Refresh above to try again.' : 'Table assignments will appear here when the organiser publishes the draw. Scores follow after each round is certified.' }}</p><button v-if="!error" class="refresh-button" @click="$emit('register')">Back to registration →</button></section>
    <p class="auto-update-note">Updates automatically every 30 seconds. Draft scores stay private.</p>
  </div>
</template>

<script setup>
const props = defineProps({ event: Object, snapshot: Object, updatedAt: String, loading: Boolean, refreshing: Boolean, error: String })
defineEmits(['refresh', 'register'])
const search = ref('')
const phases = [{ key: 'registration', label: 'Registration' }, { key: 'qualifier_1', label: 'Qualifier 1' }, { key: 'qualifier_2', label: 'Qualifier 2' }, { key: 'final', label: 'Final' }]
const phaseIndex = computed(() => props.event?.stage === 'completed' ? 4 : Math.max(0, phases.findIndex(phase => phase.key === props.event?.stage)))
const formattedUpdate = computed(() => props.updatedAt ? new Date(props.updatedAt).toLocaleString('en-MY', { timeZone: 'Asia/Kuala_Lumpur', dateStyle: 'medium', timeStyle: 'short' }) : 'Awaiting publication')
const assignments = computed(() => { const key = props.snapshot?.assignment_round; return key ? props.snapshot?.assignments?.[key] ?? [] : Object.values(props.snapshot?.assignments ?? {})[0] ?? [] })
const matches = name => String(name ?? '').toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase())
const filteredAssignments = computed(() => assignments.value.filter(table => table.seats.some(seat => matches(seat.display_name))))
const filteredStandings = computed(() => (props.snapshot?.standings ?? []).filter(row => matches(row.display_name)))
function isFinalist(row) { return props.snapshot?.top_four?.some(person => person.participant_id === row.participant_id) }
function humanize(value = '') { return String(value).replaceAll('_', ' ').replace(/\b\w/g, char => char.toUpperCase()) }
function score(value) { return value == null ? '—' : `${Number(value) > 0 ? '+' : ''}${Number(value).toFixed(1)}` }
function deduction(value) { return value == null ? '—' : Number(value) > 0 ? `−${Number(value).toFixed(1)}` : '0.0' }
function ordinal(value) { const n = Number(value); return `${n}${n === 1 ? 'st' : n === 2 ? 'nd' : n === 3 ? 'rd' : 'th'}` }
</script>

<style scoped>
.results-heading{padding:0;text-align:left;width:100%}
.event-results{padding:28px 0 40px}.results-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin:8px 0 28px}.eyebrow{color:var(--gold-leaf);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;margin:0 0 10px}.results-heading h1{font:400 clamp(2.6rem,6vw,4.6rem)/1.08 var(--font-display);color:var(--matcha-leaf);margin:0}.results-heading h1 em{color:var(--gold-leaf)}.results-heading p:last-child,.empty-results>p:not(.eyebrow),.waiting-scores p{color:var(--muted);line-height:1.7;max-width:580px}.refresh-button{min-height:44px;flex-shrink:0;border:1px solid var(--line);border-radius:8px;background:var(--white-pure);padding:10px 16px;color:var(--matcha-leaf);font:600 .84rem var(--font-body);cursor:pointer}.refresh-button:disabled{opacity:.6;cursor:wait}.round-progress{list-style:none;display:grid;grid-template-columns:repeat(4,1fr);padding:20px 8px;margin:0 0 24px;border:1px solid var(--line);border-radius:12px;background:var(--white-pure)}.round-progress li{display:grid;grid-template-columns:30px 1fr;gap:0 10px;padding:0 16px;border-right:1px solid var(--line);color:var(--muted)}.round-progress li:last-child{border:0}.round-progress li>span{grid-row:span 2;display:grid;place-items:center;width:30px;height:30px;border:1px solid var(--line);border-radius:50%;font-size:.8rem}.round-progress strong{font-size:.83rem}.round-progress small{font-size:.68rem}.round-progress .current{color:var(--matcha-leaf)}.round-progress .current>span{background:var(--matcha-leaf);color:white;border-color:var(--matcha-leaf)}.round-progress .done>span{background:#e5ece3;color:var(--matcha-leaf)}.results-card{padding:clamp(20px,3vw,32px);background:var(--white-pure);border:1px solid var(--line);border-radius:12px;margin:20px 0;box-shadow:var(--shadow-card)}.results-card h2{font:400 clamp(1.6rem,3vw,2rem) var(--font-display);color:var(--matcha-leaf);margin:0}.card-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.soft-badge{padding:6px 10px;border-radius:30px;background:var(--surface-soft);color:var(--matcha-leaf);font-size:.72rem;white-space:nowrap}.results-toolbar{display:flex;align-items:end;justify-content:space-between;gap:20px}.player-search{display:grid;gap:6px;max-width:350px;flex:1;font-size:.8rem;font-weight:600}.player-search input{min-height:46px;padding:10px 14px;font:400 .94rem var(--font-body);border:1px solid var(--line);background:var(--white-pure);width:100%}.update-note{font-size:.73rem;color:var(--muted);text-align:right;margin:0 0 3px}.update-note strong{display:block;font-weight:500;margin-top:3px}.live-dot{display:inline-block;width:6px;height:6px;margin-right:6px;border-radius:50%;background:#6b8565}.seating-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin-top:22px}.seating-grid article{border:1px solid var(--line);border-radius:9px;overflow:hidden}.seating-grid h3{display:flex;justify-content:space-between;align-items:center;margin:0;padding:12px 15px;background:var(--surface-soft);font-size:.85rem;font-weight:500;color:var(--matcha-leaf)}.seating-grid h3 strong{font:1.4rem var(--font-display)}.seating-grid ul{list-style:none;margin:0;padding:5px 14px}.seating-grid li{display:flex;gap:12px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line);font-size:.83rem;overflow-wrap:anywhere}.seating-grid li:last-child{border:0}.seating-grid li>strong{min-width:0}.wind-label{color:var(--muted);width:43px;flex-shrink:0;font-size:.73rem}.seating-grid .matched-player{background:#f1ecd9}.table-note,.no-matches{font-size:.82rem;line-height:1.6;color:var(--muted)}.table-scroll{overflow:auto}.table-scroll table{width:100%;border-collapse:collapse;font-size:.86rem}.table-scroll th,.table-scroll td{padding:14px 10px;text-align:left;border-bottom:1px solid var(--line)}.table-scroll thead th{font-size:.7rem;color:var(--muted);font-weight:600}.table-scroll tbody th{font-weight:600;min-width:180px}.table-scroll tbody small{display:block;font-size:.69rem;margin-top:3px;color:var(--muted)}.finalist{background:#f2f2e8}.rank-number{display:inline-grid;place-items:center;min-width:30px;height:30px;border-radius:7px;background:var(--surface-soft);color:var(--matcha-leaf);font-size:.8rem}.total-score{font-weight:750;font-variant-numeric:tabular-nums;color:var(--matcha-leaf)}.finalist-label{color:var(--gold-leaf)!important}.mobile-standings{display:none}.champion-card{background:radial-gradient(ellipse at 100% 0,#e4dfc5,transparent 70%),var(--white-pure);border-color:#cdbb8c}.champion-card h2{font-size:clamp(2rem,4vw,3rem)}.champion-card>p:not(.eyebrow){color:var(--muted)}.champion-card ol{padding:0;list-style:none}.champion-card li{display:grid;grid-template-columns:40px 1fr auto;gap:12px;border-top:1px solid #dcd4bd;padding:12px 0}.champion-card li>strong{color:var(--gold-leaf)}.champion-card small{color:var(--muted)}.empty-results{text-align:center;padding:54px 24px}.empty-results>p{margin-inline:auto}.empty-tile{display:grid;place-items:center;width:56px;height:70px;margin:0 auto 24px;border:1px solid #d6d3bf;border-bottom:5px solid #9eac91;border-radius:8px;background:#fbf9ee;color:var(--gold-leaf);font:2rem var(--font-display);transform:rotate(-7deg)}.empty-results .refresh-button{margin-top:8px}.results-notice{padding:12px 16px;border-radius:8px;background:#f6ecd6;color:#70572d;font-size:.85rem}.auto-update-note{text-align:center;color:var(--muted);font-size:.72rem;margin:24px 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:650px){.event-results{padding-top:14px}.results-heading{gap:10px}.results-heading .refresh-button{padding-inline:12px;margin-top:5px}.results-heading p:last-child{font-size:.88rem}.round-progress{padding:14px 4px}.round-progress li{display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px;padding:0 4px}.round-progress strong{font-size:.68rem}.round-progress small{display:none}.round-progress li>span{width:26px;height:26px}.results-toolbar{align-items:stretch;flex-direction:column;gap:12px}.player-search{max-width:none}.update-note{text-align:left}.update-note strong{display:inline;margin-left:5px}.card-heading{align-items:flex-start}.soft-badge{font-size:.62rem}.seating-grid{grid-template-columns:1fr}.desktop-standings{display:none}.mobile-standings{display:grid;padding:0;list-style:none;margin:18px 0 0;gap:10px}.mobile-standings>li{padding:14px;border:1px solid var(--line);border-radius:9px}.player-line{display:flex;gap:12px;align-items:center;font-size:.88rem}.player-line>div{flex:1;min-width:0;overflow-wrap:anywhere}.player-line small{display:block;font-size:.65rem;font-weight:400;color:var(--muted)}.player-line>.total-score{text-align:right;flex-shrink:0;font-size:1.1rem}.mobile-standings dl{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding-top:12px;margin:12px 0 0;border-top:1px solid var(--line)}.mobile-standings dt{font-size:.63rem;color:var(--muted)}.mobile-standings dd{margin:3px 0 0;font-size:.83rem;font-variant-numeric:tabular-nums}.champion-card li{font-size:.85rem;gap:8px}}
</style>
